#include <bits/stdc++.h>
using namespace std;
// Arbitrary-precision non-negative integer, base 1e9, little-endian limbs.
typedef vector<uint32_t> Big;
const uint64_t BASE = 1000000000ULL;
void mulSmall(Big &a, uint64_t m) {
    uint64_t carry = 0;
    for (auto &x : a) { uint64_t cur = x * m + carry; x = cur % BASE; carry = cur / BASE; }
    while (carry) { a.push_back(carry % BASE); carry /= BASE; }
    while (a.size() > 1 && a.back() == 0) a.pop_back();
}
void divSmall(Big &a, uint64_t d) {
    uint64_t rem = 0;
    for (int i = (int)a.size() - 1; i >= 0; i--) { uint64_t cur = a[i] + rem * BASE; a[i] = cur / d; rem = cur % d; }
    while (a.size() > 1 && a.back() == 0) a.pop_back();
}
void addTo(Big &a, const Big &b) {
    if (a.size() < b.size()) a.resize(b.size(), 0);
    uint64_t carry = 0;
    for (size_t i = 0; i < a.size(); i++) {
        uint64_t cur = a[i] + carry + (i < b.size() ? b[i] : 0);
        a[i] = cur % BASE; carry = cur / BASE;
    }
    if (carry) a.push_back(carry);
}
