import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long n = nextLong(), minimum = nextLong(), lo = nextLong(), hi = nextLong();
        long m = 0;
        for (long i = 0; i < n; i++) {
            long v = nextLong();
            if (lo <= v && v <= hi) m++;
        }
        java.math.BigInteger choose = java.math.BigInteger.ONE, answer = java.math.BigInteger.ZERO;
        for (long k = 0; k <= m; k++) {
            if (k >= minimum) answer = answer.add(choose);
            if (k < m) choose = choose.multiply(java.math.BigInteger.valueOf(m - k)).divide(java.math.BigInteger.valueOf(k + 1));
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"math/big"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, minimum, lo, hi := nextInt(), nextInt(), nextInt(), nextInt()
	var m int64
	for i := int64(0); i < n; i++ {
		if v := nextInt(); lo <= v && v <= hi {
			m++
		}
	}
	choose, answer := big.NewInt(1), big.NewInt(0)
	t := new(big.Int)
	for k := int64(0); k <= m; k++ {
		if k >= minimum {
			answer.Add(answer, choose)
		}
		if k < m {
			choose.Mul(choose, t.SetInt64(m-k))
			choose.Quo(choose, t.SetInt64(k+1))
		}
	}
	w.WriteString(answer.String() + "\n")
}
